/**
 * Reader for assets/data/exam_blueprints.json (canonical, generated by
 * gen_blueprints_2026.js). Parsing is tolerant: unknown fields pass through,
 * only the fields the pipeline relies on are required.
 */
import { z } from 'zod';
import { ItemType, Language } from './schema';
import { readJson } from './io';

const L10n = z.looseObject({ ru: z.string().optional(), ky: z.string().optional(), en: z.string().optional() });

export const BlueprintPart = z.looseObject({
  id: z.string(),
  title: L10n,
  question_count: z.number().int().min(1),
  options_per_question: z.number().int().min(2).max(5),
  item_type: ItemType,
  verified: z.boolean(),
  fixed_options: z.array(z.looseObject({ id: z.string(), text: L10n })).optional(),
  note: z.string().optional(),
});
export type BlueprintPart = z.infer<typeof BlueprintPart>;

export const BlueprintSection = z.looseObject({
  id: z.string(),
  order: z.number().int(),
  title: L10n,
  question_count: z.number().int().min(1),
  duration_minutes: z.number().min(1),
  points_per_question: z.number(),
  subject_area: z.string(),
  uses_passages: z.boolean(),
  language_specific: z.boolean().optional(),
  difficulty_mix: z.record(z.string(), z.number()),
  passage_layout: z
    .looseObject({ standalone_texts: z.number().int(), paired_texts: z.number().int(), words_min: z.number(), words_max: z.number() })
    .optional(),
  task_types: z.array(z.string()).optional(),
  parts: z.array(BlueprintPart).min(1),
});
export type BlueprintSection = z.infer<typeof BlueprintSection>;

export const Blueprint = z.looseObject({
  id: z.string(),
  kind: z.enum(['main', 'subject', 'state_language']),
  subject_id: z.string().nullable(),
  exam_year: z.number().int(),
  version: z.number().int().min(1),
  status: z.string(),
  title: L10n,
  languages: z.array(Language).min(1),
  options_per_question: z.number().int(),
  sections: z.array(BlueprintSection).min(1),
});
export type Blueprint = z.infer<typeof Blueprint>;

export const BlueprintFile = z.looseObject({
  schema_version: z.number().int(),
  blueprints: z.array(Blueprint).min(1),
});
export type BlueprintFile = z.infer<typeof BlueprintFile>;

export function loadBlueprints(path: string): Blueprint[] {
  const parsed = BlueprintFile.parse(readJson(path));
  for (const bp of parsed.blueprints) {
    for (const s of bp.sections) {
      const sum = s.parts.reduce((a, p) => a + p.question_count, 0);
      if (sum !== s.question_count) throw new Error(`${bp.id}/${s.id}: parts sum ${sum} != question_count ${s.question_count}`);
    }
  }
  return parsed.blueprints;
}

/** Raw blueprint documents exactly as stored in the JSON (for import — nothing is dropped). */
export function loadRawBlueprints(path: string): Array<Record<string, unknown>> {
  const raw = readJson<{ blueprints: Array<Record<string, unknown>> }>(path);
  return raw.blueprints;
}

export function getBlueprint(blueprints: Blueprint[], id: string): Blueprint {
  const bp = blueprints.find((b) => b.id === id);
  if (!bp) throw new Error(`Unknown blueprint ${id}. Known: ${blueprints.map((b) => b.id).join(', ')}`);
  return bp;
}

export function findPart(bp: Blueprint, sectionId: string, partId: string): { section: BlueprintSection; part: BlueprintPart } {
  const section = bp.sections.find((s) => s.id === sectionId);
  if (!section) throw new Error(`${bp.id}: no section ${sectionId}`);
  const part = section.parts.find((p) => p.id === partId);
  if (!part) throw new Error(`${bp.id}/${sectionId}: no part ${partId}`);
  return { section, part };
}

/** Fixed options of a quantitative_comparison part in one language (A..D). */
export function fixedOptionsFor(part: BlueprintPart, language: string): Array<{ id: string; text: string }> | null {
  if (!part.fixed_options) return null;
  return part.fixed_options.map((o) => {
    const text = (o.text as Record<string, string | undefined>)[language] ?? o.text.ru ?? '';
    return { id: o.id, text };
  });
}

export function sectionsInOrder(bp: Blueprint): BlueprintSection[] {
  return [...bp.sections].sort((a, b) => a.order - b.order);
}

export const BLUEPRINT_DIFFICULTY_LEVELS = ['1', '2', '3'] as const;
